-- ===================================================================== -- Create ONE pregnancy cycle per patient -- Ensures exactly ONE cycle per person_uuid by pre-aggregating data -- ===================================================================== INSERT INTO pmtct_pregnancy_cycle ( person_uuid, maternal_outcome, entry_point, hiv_status, pregnancy_outcome, number_of_infants, pmtct_status, facility_id, created_by, created_date, last_modified_by, last_modified_date, uuid, archived, is_closed ) WITH -- Get all unique person_uuids from both tables all_patients AS ( SELECT DISTINCT person_uuid FROM pmtct_anc WHERE person_uuid IS NOT NULL UNION SELECT DISTINCT person_uuid FROM pmtct_enrollment WHERE person_uuid IS NOT NULL ), -- Get the latest/most relevant ANC record per patient latest_anc AS ( SELECT DISTINCT ON (person_uuid) person_uuid, id, anc_no, static_hiv_status, status, facility_id, created_by, created_date, last_modified_by, last_modified_date, archived FROM pmtct_anc WHERE person_uuid IS NOT NULL ORDER BY person_uuid, created_date DESC NULLS LAST, id DESC ), -- Get the latest/most relevant enrollment record per patient latest_enrollment AS ( SELECT DISTINCT ON (person_uuid) person_uuid, id, anc_no, hiv_status, entry_point, facility_id, created_by, created_date, last_modified_by, last_modified_date, archived FROM pmtct_enrollment WHERE person_uuid IS NOT NULL ORDER BY person_uuid, created_date DESC NULLS LAST, id DESC ), -- Get latest HTS result per patient latest_hts AS ( SELECT DISTINCT ON (person_uuid) person_uuid, final_result FROM pmtct_hts WHERE person_uuid IS NOT NULL ORDER BY person_uuid, id DESC ), -- Get latest delivery record per patient latest_delivery AS ( SELECT DISTINCT ON (person_uuid) person_uuid, child_status, maternal_outcome, number_of_infants_alive, number_of_infants_dead FROM pmtct_delivery WHERE person_uuid IS NOT NULL ORDER BY person_uuid, created_date DESC NULLS LAST, id DESC ) -- Now join everything to create ONE record per patient SELECT ap.person_uuid,
-- maternal_outcome: From delivery.child_status, else NULL d.maternal_outcome as maternal_outcome,
-- entry_point: ANC if has ANC record, else map enrollment CASE WHEN a.id IS NOT NULL THEN 'ANC' WHEN e.entry_point = 'PMTCT_ENTRY_POINT_ANC' THEN 'ANC' WHEN e.entry_point = 'PMTCT_ENTRY_POINT_POST-PARTUM' THEN 'Post-partum' WHEN e.entry_point = 'PMTCT_ENTRY_POINT_LD' THEN 'LD' WHEN e.entry_point IS NOT NULL THEN e.entry_point ELSE 'ANC' END as entry_point,
-- hiv_status: Priority - enrollment > latest HTS > ANC COALESCE( e.hiv_status, hts.final_result, a.static_hiv_status ) as hiv_status,
-- pregnancy_outcome: From delivery.child_status d.child_status as pregnancy_outcome,
-- number_of_infants: From delivery (sum of alive and dead) COALESCE(d.number_of_infants_alive, 0) + COALESCE(d.number_of_infants_dead, 0) as number_of_infants,
-- pmtct_status: Always ACTIVE for existing patients 'ACTIVE' as pmtct_status,
-- Audit fields: Prefer ANC, fallback to enrollment COALESCE(a.facility_id, e.facility_id) as facility_id, COALESCE(a.created_by, e.created_by) as created_by, COALESCE(a.created_date, e.created_date) as created_date, COALESCE(a.last_modified_by, e.last_modified_by) as last_modified_by, COALESCE(a.last_modified_date, e.last_modified_date, a.created_date, e.created_date) as last_modified_date, gen_random_uuid() as uuid,
-- archived: Prefer ANC, fallback to enrollment COALESCE(a.archived, e.archived, 0) as archived,
-- is_closed: TRUE if terminal maternal outcome CASE WHEN d.maternal_outcome IN ( 'MATERNAL_OUTCOME_DEAD', 'MATERNAL_OUTCOME_LOST_TO_FOLLOW-UP', 'MATERNAL_OUTCOME_TRANSFERRED_OUT' ) THEN TRUE ELSE FALSE END as is_closed
FROM all_patients ap LEFT JOIN latest_anc a ON ap.person_uuid = a.person_uuid LEFT JOIN latest_enrollment e ON ap.person_uuid = e.person_uuid LEFT JOIN latest_hts hts ON ap.person_uuid = hts.person_uuid LEFT JOIN latest_delivery d ON ap.person_uuid = d.person_uuid;
-- Update infant counts from actual records UPDATE pmtct_pregnancy_cycle pc SET number_of_infants = infant_count.total FROM ( SELECT i.mother_person_uuid, COUNT(DISTINCT i.id) as total, MIN(i.created_date) as first_created FROM pmtct_infant_information i WHERE i.mother_person_uuid IS NOT NULL GROUP BY i.mother_person_uuid ) infant_count WHERE pc.person_uuid = infant_count.mother_person_uuid AND ABS(EXTRACT(EPOCH FROM (infant_count.first_created - pc.created_date))) < 31536000 AND infant_count.total > COALESCE(pc.number_of_infants, 0);
-- ===================================================================== -- Link all existing records to their pregnancy cycles -- =====================================================================
-- Update pmtct_anc UPDATE pmtct_anc a SET pmtct_cycle_id = pc.id FROM pmtct_pregnancy_cycle pc WHERE a.person_uuid = pc.person_uuid AND a.pmtct_cycle_id IS NULL;
-- Update pmtct_enrollment UPDATE pmtct_enrollment e SET pmtct_cycle_id = pc.id FROM pmtct_pregnancy_cycle pc WHERE e.person_uuid = pc.person_uuid AND e.pmtct_cycle_id IS NULL;
-- Update pmtct_delivery UPDATE pmtct_delivery d SET pmtct_cycle_id = pc.id FROM pmtct_pregnancy_cycle pc WHERE d.person_uuid = pc.person_uuid AND d.pmtct_cycle_id IS NULL;
-- Update pmtct_mother_visitation UPDATE pmtct_mother_visitation mv SET pmtct_cycle_id = pc.id FROM pmtct_pregnancy_cycle pc WHERE mv.person_uuid = pc.person_uuid AND mv.pmtct_cycle_id IS NULL;
-- Update pmtct_infant_information (using mother_person_uuid) UPDATE pmtct_infant_information ii SET pmtct_cycle_id = pc.id FROM pmtct_pregnancy_cycle pc WHERE ii.mother_person_uuid = pc.person_uuid AND ii.pmtct_cycle_id IS NULL;
-- Update pmtct_infant_mother_art (using mother_person_uuid) UPDATE pmtct_infant_mother_art ima SET pmtct_cycle_id = pc.id FROM pmtct_pregnancy_cycle pc WHERE ima.mother_person_uuid = pc.person_uuid AND ima.mother_person_uuid IS NOT NULL AND ima.pmtct_cycle_id IS NULL;
-- Update pmtct_infant_arv (using mother_person_uuid) UPDATE pmtct_infant_arv ia SET pmtct_cycle_id = pc.id FROM pmtct_pregnancy_cycle pc WHERE ia.mother_person_uuid = pc.person_uuid AND ia.mother_person_uuid IS NOT NULL AND ia.pmtct_cycle_id IS NULL;
-- Update pmtct_infant_pcr (using mother_person_uuid) UPDATE pmtct_infant_pcr ip SET pmtct_cycle_id = pc.id FROM pmtct_pregnancy_cycle pc WHERE ip.mother_person_uuid = pc.person_uuid AND ip.mother_person_uuid IS NOT NULL AND ip.pmtct_cycle_id IS NULL;
-- Update pmtct_infant_visit (using mother_person_uuid) UPDATE pmtct_infant_visit iv SET pmtct_cycle_id = pc.id FROM pmtct_pregnancy_cycle pc WHERE iv.mother_person_uuid = pc.person_uuid AND iv.pmtct_cycle_id IS NULL;
-- Update pmtct_infant_rapid_antibody (using mother_person_uuid) UPDATE pmtct_infant_rapid_antibody ira SET pmtct_cycle_id = pc.id FROM pmtct_pregnancy_cycle pc WHERE ira.mother_person_uuid = pc.person_uuid AND ira.mother_person_uuid IS NOT NULL AND ira.pmtct_cycle_id IS NULL;
-- Update pmtct_hts UPDATE pmtct_hts h SET pmtct_cycle_id = pc.id FROM pmtct_pregnancy_cycle pc WHERE h.person_uuid = pc.person_uuid AND h.pmtct_cycle_id IS NULL;

DO $$
DECLARE
rec RECORD;
    v_total INTEGER;
    v_anc_entry INTEGER;
    v_ld_entry INTEGER;
    v_pp_entry INTEGER;
    v_duplicates INTEGER;
    v_anc_only INTEGER;
    v_pmtct_only INTEGER;
    v_both INTEGER;
BEGIN
SELECT COUNT(*) INTO v_total FROM pmtct_pregnancy_cycle;

-- Check for duplicates
SELECT COUNT(*) INTO v_duplicates
FROM (
         SELECT person_uuid, COUNT(*) as cnt
         FROM pmtct_pregnancy_cycle
         GROUP BY person_uuid
         HAVING COUNT(*) > 1
     ) dups;

SELECT COUNT(*) INTO v_anc_entry
FROM pmtct_pregnancy_cycle WHERE entry_point = 'ANC';

SELECT COUNT(*) INTO v_ld_entry
FROM pmtct_pregnancy_cycle WHERE entry_point = 'LD';

SELECT COUNT(*) INTO v_pp_entry
FROM pmtct_pregnancy_cycle WHERE entry_point = 'Post-partum';

-- Source analysis
SELECT COUNT(DISTINCT pc.person_uuid) INTO v_anc_only
FROM pmtct_pregnancy_cycle pc
         INNER JOIN pmtct_anc a ON pc.person_uuid = a.person_uuid
WHERE NOT EXISTS (
    SELECT 1 FROM pmtct_enrollment e
    WHERE e.person_uuid = pc.person_uuid
);

SELECT COUNT(DISTINCT pc.person_uuid) INTO v_pmtct_only
FROM pmtct_pregnancy_cycle pc
         INNER JOIN pmtct_enrollment e ON pc.person_uuid = e.person_uuid
WHERE NOT EXISTS (
    SELECT 1 FROM pmtct_anc a
    WHERE a.person_uuid = pc.person_uuid
);

SELECT COUNT(DISTINCT pc.person_uuid) INTO v_both
FROM pmtct_pregnancy_cycle pc
WHERE EXISTS (SELECT 1 FROM pmtct_anc a WHERE a.person_uuid = pc.person_uuid)
  AND EXISTS (SELECT 1 FROM pmtct_enrollment e WHERE e.person_uuid = pc.person_uuid);

RAISE NOTICE '================================================================';
    RAISE NOTICE '     PREGNANCY CYCLE MIGRATION - ONE CYCLE PER PATIENT';
    RAISE NOTICE '================================================================';
    RAISE NOTICE '';
    RAISE NOTICE 'TOTAL CYCLES CREATED: %', v_total;
    RAISE NOTICE '';

    IF v_duplicates > 0 THEN
        RAISE WARNING 'WARNING: % patients have DUPLICATE cycles!', v_duplicates;
ELSE
        RAISE NOTICE 'SUCCESS: NO DUPLICATES - Each patient has ONE cycle';
END IF;
    RAISE NOTICE '';

    RAISE NOTICE 'SOURCE BREAKDOWN:';
    RAISE NOTICE '  ANC only: %', v_anc_only;
    RAISE NOTICE '  PMTCT only: %', v_pmtct_only;
    RAISE NOTICE '  BOTH: %', v_both;
    RAISE NOTICE '  Total: % (should equal %)', v_anc_only + v_pmtct_only + v_both, v_total;
    RAISE NOTICE '';

    RAISE NOTICE 'ENTRY POINTS:';
    RAISE NOTICE '  ANC: %', v_anc_entry;
    RAISE NOTICE '  LD: %', v_ld_entry;
    RAISE NOTICE '  Post-partum: %', v_pp_entry;
    RAISE NOTICE '';
    RAISE NOTICE '================================================================';
END $$;

