UPDATE pmtct_enrollment
SET syphilis_details = jsonb_build_object(
    'testResult', COALESCE(syphilis_test_result, ''),
    'treatment', COALESCE(syphilis_treatment, ''),
    'drugName', COALESCE(syphilis_drug_name, '')
)
WHERE syphilis_test_result IS NOT NULL
  AND syphilis_details IS NULL;

ALTER TABLE pmtct_enrollment DROP COLUMN IF EXISTS syphilis_test_result;
ALTER TABLE pmtct_enrollment DROP COLUMN IF EXISTS syphilis_treatment;
ALTER TABLE pmtct_enrollment DROP COLUMN IF EXISTS syphilis_drug_name;

-- 1. Map "Previous" variants + "Previously known HIV positive (ANC)" -> Previously in Care/ART UPDATE pmtct_enrollment SET time_of_hiv_diagnosis = ( SELECT code FROM base_application_codeset WHERE codeset_group = 'PERIOD_DIAGNOSED_HIV' AND display = 'Previously in Care/ART' LIMIT 1 ) WHERE time_of_hiv_diagnosis IN ( SELECT code FROM base_application_codeset WHERE codeset_group = 'TIME_HIV_DIAGNOSIS' AND ( display ILIKE '%Non pregnant%' OR display ILIKE '%Previous pregnancy%' OR display ILIKE '%Previously known HIV%positive%' ) );
-- 2. Map "ANC" and "Newly tested HIV positive (ANC)" -> ANC UPDATE pmtct_enrollment SET time_of_hiv_diagnosis = ( SELECT code FROM base_application_codeset WHERE codeset_group = 'PERIOD_DIAGNOSED_HIV' AND display = 'ANC' LIMIT 1 ) WHERE time_of_hiv_diagnosis IN ( SELECT code FROM base_application_codeset WHERE codeset_group = 'TIME_HIV_DIAGNOSIS' AND ( display = 'ANC' OR display ILIKE '%Newly tested HIV positive%' ) );
-- 3. Map "Labour" -> Labour UPDATE pmtct_enrollment SET time_of_hiv_diagnosis = ( SELECT code FROM base_application_codeset WHERE codeset_group = 'PERIOD_DIAGNOSED_HIV' AND display = 'Labour' LIMIT 1 ) WHERE time_of_hiv_diagnosis IN ( SELECT code FROM base_application_codeset WHERE codeset_group = 'TIME_HIV_DIAGNOSIS' AND display = 'Labour' );
-- 4. Map "Post Partum <=72hrs" -> 72 hrs Postpartum -- Note: old codeset has identical display for <=72 and >72, so match by code pattern (LT = less than) UPDATE pmtct_enrollment SET time_of_hiv_diagnosis = ( SELECT code FROM base_application_codeset WHERE codeset_group = 'PERIOD_DIAGNOSED_HIV' AND display ILIKE '%Postpartum%' AND display ILIKE '%72%' LIMIT 1 ) WHERE time_of_hiv_diagnosis IN ( SELECT code FROM base_application_codeset WHERE codeset_group = 'TIME_HIV_DIAGNOSIS' AND code ILIKE '%POST_PARTUM%LT%' );
-- 5. Map "Post Partum >72hrs" -> Breastfeeding Period -- Note: old codeset has identical display for <=72 and >72, so match by code pattern (GT = greater than) UPDATE pmtct_enrollment SET time_of_hiv_diagnosis = ( SELECT code FROM base_application_codeset WHERE codeset_group = 'PERIOD_DIAGNOSED_HIV' AND display ILIKE '%Breastfeeding%' LIMIT 1 ) WHERE time_of_hiv_diagnosis IN ( SELECT code FROM base_application_codeset WHERE codeset_group = 'TIME_HIV_DIAGNOSIS' AND code ILIKE '%POST_PARTUM%GT%' );

-- 1. Map "Previous" variants + "Previously known HIV positive (ANC)" -> Previously in Care/ART UPDATE pmtct_anc SET hiv_diognosic_time = ( SELECT code FROM base_application_codeset WHERE codeset_group = 'PERIOD_DIAGNOSED_HIV' AND display = 'Previously in Care/ART' LIMIT 1 ) WHERE hiv_diognosic_time IN ( SELECT code FROM base_application_codeset WHERE codeset_group = 'TIME_HIV_DIAGNOSIS' AND ( display ILIKE '%Non pregnant%' OR display ILIKE '%Previous pregnancy%' OR display ILIKE '%Previously known HIV%positive%' ) );
-- 2. Map "ANC" and "Newly tested HIV positive (ANC)" -> ANC UPDATE pmtct_anc SET hiv_diognosic_time = ( SELECT code FROM base_application_codeset WHERE codeset_group = 'PERIOD_DIAGNOSED_HIV' AND display = 'ANC' LIMIT 1 ) WHERE hiv_diognosic_time IN ( SELECT code FROM base_application_codeset WHERE codeset_group = 'TIME_HIV_DIAGNOSIS' AND ( display = 'ANC' OR display ILIKE '%Newly tested HIV positive%' ) );
-- 3. Map "Labour" -> Labour UPDATE pmtct_anc SET hiv_diognosic_time = ( SELECT code FROM base_application_codeset WHERE codeset_group = 'PERIOD_DIAGNOSED_HIV' AND display = 'Labour' LIMIT 1 ) WHERE hiv_diognosic_time IN ( SELECT code FROM base_application_codeset WHERE codeset_group = 'TIME_HIV_DIAGNOSIS' AND display = 'Labour' );
-- 4. Map "Post Partum <=72hrs" -> 72 hrs Postpartum -- Note: old codeset has identical display for <=72 and >72, so match by code pattern (LT = less than) UPDATE pmtct_anc SET hiv_diognosic_time = ( SELECT code FROM base_application_codeset WHERE codeset_group = 'PERIOD_DIAGNOSED_HIV' AND display ILIKE '%Postpartum%' AND display ILIKE '%72%' LIMIT 1 ) WHERE hiv_diognosic_time IN ( SELECT code FROM base_application_codeset WHERE codeset_group = 'TIME_HIV_DIAGNOSIS' AND code ILIKE '%POST_PARTUM%LT%' );
-- 5. Map "Post Partum >72hrs" -> Breastfeeding Period -- Note: old codeset has identical display for <=72 and >72, so match by code pattern (GT = greater than) UPDATE pmtct_anc SET hiv_diognosic_time = ( SELECT code FROM base_application_codeset WHERE codeset_group = 'PERIOD_DIAGNOSED_HIV' AND display ILIKE '%Breastfeeding%' LIMIT 1 ) WHERE hiv_diognosic_time IN ( SELECT code FROM base_application_codeset WHERE codeset_group = 'TIME_HIV_DIAGNOSIS' AND code ILIKE '%POST_PARTUM%GT%' );

-- Merge hepatitisb into existing hbv_details (add testResult key)
UPDATE pmtct_enrollment
SET hbv_details = COALESCE(hbv_details, '{}'::jsonb) || jsonb_build_object('testResult', COALESCE(hepatitisb, ''))
WHERE hepatitisb IS NOT NULL
  AND (hbv_details IS NULL OR NOT jsonb_exists(hbv_details, 'testResult') OR hbv_details->>'testResult' = '');

ALTER TABLE pmtct_enrollment DROP COLUMN hepatitisb;

UPDATE pmtct_pregnancy_cycle
SET uuid = gen_random_uuid()::varchar
WHERE uuid IS NULL OR uuid = '';

UPDATE pmtct_anc SET pmtct_cycle_uuid = (
    SELECT ppc.uuid::uuid FROM pmtct_pregnancy_cycle ppc WHERE ppc.id = pmtct_anc.pmtct_cycle_id
) WHERE pmtct_cycle_id IS NOT NULL AND pmtct_cycle_uuid IS NULL;

UPDATE pmtct_enrollment SET pmtct_cycle_uuid = (
    SELECT ppc.uuid::uuid FROM pmtct_pregnancy_cycle ppc WHERE ppc.id = pmtct_enrollment.pmtct_cycle_id
) WHERE pmtct_cycle_id IS NOT NULL AND pmtct_cycle_uuid IS NULL;

UPDATE pmtct_delivery SET pmtct_cycle_uuid = (
