ALTER TABLE pmtct_infant_rapid_antibody ADD CONSTRAINT fk_infant_rapid_pregnancy_cycle_uuid FOREIGN KEY (pmtct_cycle_uuid) REFERENCES pmtct_pregnancy_cycle(uuid);
ALTER TABLE pmtct_hts ADD CONSTRAINT fk_hts_pregnancy_cycle_uuid FOREIGN KEY (pmtct_cycle_uuid) REFERENCES pmtct_pregnancy_cycle(uuid);

DO $$
DECLARE
    tbl TEXT;
    max_id BIGINT;
    seq_name TEXT;
    has_identity BOOLEAN;
BEGIN
    FOREACH tbl IN ARRAY ARRAY[
        'pmtct_pregnancy_cycle', 'pmtct_infant_information', 'pmtct_infant_arv',
        'pmtct_infant_pcr', 'pmtct_infant_mother_art', 'pmtct_infant_visit',
        'pmtct_infant_rapid_antibody', 'pmtct_anc', 'pmtct_enrollment',
        'pmtct_delivery', 'pmtct_hts', 'pmtct_mother_visitation'
    ] LOOP
        -- Check if column already has IDENTITY
        SELECT EXISTS (
            SELECT 1 FROM information_schema.columns
            WHERE table_name = tbl AND column_name = 'id'
            AND is_identity = 'YES'
        ) INTO has_identity;

        -- Only create sequence if IDENTITY is missing
        IF NOT has_identity THEN
            seq_name := tbl || '_id_seq';
            EXECUTE format('SELECT COALESCE(MAX(id), 0) FROM %I', tbl) INTO max_id;
            EXECUTE format('DROP SEQUENCE IF EXISTS %I CASCADE', seq_name);
            EXECUTE format('CREATE SEQUENCE %I START WITH %s', seq_name, max_id + 1);
            EXECUTE format('ALTER TABLE %I ALTER COLUMN id SET DEFAULT nextval(%L)', tbl, seq_name);
            EXECUTE format('UPDATE %I SET id = nextval(%L) WHERE id IS NULL', tbl, seq_name);
        END IF;
    END LOOP;
END $$;

UPDATE pmtct_delivery
SET child_status = 'CHILD_STATUS_DELIVERY_ALIVE'
WHERE child_status IS NULL OR child_status = '';

-- Dynamically fix ALL uuid-type columns across PMTCT tables to varchar
DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN
        SELECT table_name, column_name
        FROM information_schema.columns
        WHERE table_schema = 'public'
          AND table_name LIKE 'pmtct_%'
          AND udt_name = 'uuid'
    LOOP
        EXECUTE format('ALTER TABLE %I ALTER COLUMN %I TYPE varchar USING %I::varchar', r.table_name, r.column_name, r.column_name);
        RAISE NOTICE 'Fixed %.% from uuid to varchar', r.table_name, r.column_name;
    END LOOP;
END $$;

